手写堆排序 / 建堆（考频：🔥🔥）
【思路】 原地建大顶堆（从 n/2-1 逐个下沉），每次堆顶（最大）与末尾交换、堆大小减一、下沉修复。PriorityQueue 即二叉小顶堆，面试也常要求口述 siftUp/siftDown。
【复杂度】 建堆 O(n)，排序 O(n log n)/O(1)/不稳定。
【代码】（核心：下沉）
 public void heapSort(int[] a) {
 int n = a.length;
 for (int i = n / 2 - 1; i >= 0; i--) siftDown(a, i, n); // 建大顶堆
 for (int end = n - 1; end > 0; end--) {
 swap(a, 0, end); // 最大值放末尾
 siftDown(a, 0, end); // 堆大小缩小为 end
 }
}
private void siftDown(int[] a, int i, int size) {
 while (2 i + 1 < size) {
 int child = 2 i + 1;
 if (child + 1 < size && a[child + 1] > a[child]) child++;
 if (a[i] >= a[child]) break;
 swap(a, i, child);
 i = child;
 }
}

